from __future__ import annotations

import math
import re
import unicodedata
from dataclasses import dataclass
from typing import Iterable

from shapely.geometry import LineString, Point
from shapely.strtree import STRtree

from ..cad.model import CadDocument, CadEntity, CadInsert, CadLine, CadPolyline, CadText


_METRIC_DIAM_RE = re.compile(
    r'(?:\bDN|\bDIA(?:M(?:ETRO)?)?\b|Ø|\bD\s*=)\s*[-_:]?\s*(\d{1,4}(?:[.,]\d+)?)\s*(MM|CM|M)?',
    re.IGNORECASE,
)
_INCH_FRACTION_RE = re.compile(r'(?:(\d+)\s+)?(\d+)\s*/\s*(\d+)\s*["”″]')
_INCH_DECIMAL_RE = re.compile(r'(?<![\d/])(\d+(?:[.,]\d+)?)\s*["”″]')
_HEIGHT_RE = re.compile(
    r'\b(?:H|ALT(?:URA)?)\s*[:=]?\s*([+-]?\d+(?:[.,]\d+)?)\s*(MM|CM|M)?\b',
    re.IGNORECASE,
)
_ELEV_RE = re.compile(
    r'\b(?:N[IÍ]VEL|COTA|N\.?A\.?)\s*[:=]?\s*([+-]?\d+(?:[.,]\d+)?)\s*(MM|CM|M)?\b',
    re.IGNORECASE,
)

_MATERIAL_PATTERNS = (
    ('CPVC', ('CPVC',)),
    ('PPR', ('PPR',)),
    ('PEX', ('PEX',)),
    ('PVC', ('PVC',)),
    ('PEAD', ('PEAD', 'HDPE')),
    ('PBA', ('PBA',)),
    ('COBRE', ('COBRE', 'COPPER')),
    ('AÇO', ('ACO', 'AÇO', 'STEEL')),
    ('FERRO FUNDIDO', ('FERRO FUNDIDO', 'CAST IRON', 'FF')), 
    ('FERRO GALVANIZADO', ('FERRO GALVANIZADO', 'GALVANIZADO', 'GALVANISED', 'GALVANIZED')),
)

_SYSTEM_PATTERNS = {
    'cold_water': ('AGUA FRIA', 'ÁGUA FRIA', ' AF ', 'AF-', 'AF_', 'AFØ', 'AF DN'),
    'hot_water': ('AGUA QUENTE', 'ÁGUA QUENTE', ' AQ ', 'AQ-', 'AQ_', 'AQØ', 'AQ DN'),
    'sanitary': ('ESGOTO', 'SANIT', ' ESG ', 'ESG-', 'ESG_', ' ES '),
    'rainwater': ('PLUVIAL', 'AGUA PLUVIAL', 'ÁGUA PLUVIAL', ' AP ', 'AP-', 'AP_', 'APØ'),
    'fire_protection': ('INCENDIO', 'INCÊNDIO', 'HIDRANTE', 'SPRINK', 'SPK', 'FIRE'),
    'condensate': ('DRENO A.C', 'DRENO AC', 'CONDENSADO', 'CONDENSATE'),
}


@dataclass(frozen=True)
class ParsedTextFacts:
    raw_text: str
    diameter_mm: float | None = None
    diameter_source: str | None = None
    material: str | None = None
    systems: tuple[str, ...] = ()
    height_m: float | None = None
    elevation_m: float | None = None
    vertical_directive: str | None = None

    @property
    def has_semantic_fact(self) -> bool:
        return any((
            self.diameter_mm is not None,
            self.material is not None,
            bool(self.systems),
            self.height_m is not None,
            self.elevation_m is not None,
            self.vertical_directive is not None,
        ))


@dataclass(frozen=True)
class AssociatedTextEvidence:
    diameter_mm: float | None = None
    diameter_source: str | None = None
    material: str | None = None
    systems: tuple[str, ...] = ()
    height_m: float | None = None
    elevation_m: float | None = None
    vertical_directive: str | None = None
    raw_text: str | None = None
    text_ids: tuple[str, ...] = ()
    nearest_distance_m: float | None = None
    anchor_x: float | None = None
    anchor_y: float | None = None


def _plain(value: str) -> str:
    normalized = unicodedata.normalize('NFKD', value or '')
    return ''.join(ch for ch in normalized if not unicodedata.combining(ch)).upper().strip()


def _decimal(value: str) -> float:
    return float(value.replace(',', '.'))


def _metric_to_m(value: float, unit: str | None, *, infer_small_as_m: bool = True) -> float:
    unit=(unit or '').upper()
    if unit == 'MM':
        return value / 1000.0
    if unit == 'CM':
        return value / 100.0
    if unit == 'M':
        return value
    if infer_small_as_m:
        return value if abs(value) <= 20 else value / 1000.0
    return value


def _metric_diameter_to_mm(value: float, unit: str | None) -> float:
    unit=(unit or 'MM').upper()
    if unit == 'M':
        return value * 1000.0
    if unit == 'CM':
        return value * 10.0
    return value


def _detect_material(plain: str) -> str | None:
    # Longest/more specific aliases must win before generic AÇO/PVC tokens.
    for canonical, aliases in _MATERIAL_PATTERNS:
        for alias in aliases:
            if _plain(alias) in plain:
                return canonical
    return None


def _detect_systems(text: str) -> tuple[str, ...]:
    plain=f' {_plain(text)} '
    out=[]
    for system, patterns in _SYSTEM_PATTERNS.items():
        if any(_plain(pattern) in plain for pattern in patterns):
            out.append(system)
    return tuple(out)


def _vertical_directive(plain: str) -> str | None:
    if any(token in plain for token in ('DESCE', 'DOWN')):
        return 'down'
    if any(token in plain for token in ('SOBE', 'SUBINDO', 'UP', 'PRUMADA', 'RISER')):
        return 'up'
    return None


def parse_text_facts(text: str) -> ParsedTextFacts:
    raw=text or ''
    plain=_plain(raw)
    diameter_mm=None
    diameter_source=None

    metric=_METRIC_DIAM_RE.search(raw)
    if metric:
        candidate=_metric_diameter_to_mm(_decimal(metric.group(1)), metric.group(2))
        if 5 <= candidate <= 2500:
            diameter_mm=candidate
            diameter_source='metric_token'
    if diameter_mm is None:
        frac=_INCH_FRACTION_RE.search(raw)
        if frac:
            whole=float(frac.group(1) or 0)
            num=float(frac.group(2)); den=float(frac.group(3))
            if den:
                candidate=(whole + num/den) * 25.4
                if 5 <= candidate <= 2500:
                    diameter_mm=candidate
                    diameter_source='inch_fraction'
    if diameter_mm is None:
        dec=_INCH_DECIMAL_RE.search(raw)
        if dec:
            candidate=_decimal(dec.group(1))*25.4
            if 5 <= candidate <= 2500:
                diameter_mm=candidate
                diameter_source='inch_decimal'

    height_m=None
    height=_HEIGHT_RE.search(raw)
    if height:
        height_m=_metric_to_m(_decimal(height.group(1)), height.group(2))
        if not -100 <= height_m <= 100:
            height_m=None

    elevation_m=None
    elev=_ELEV_RE.search(raw)
    if elev:
        elevation_m=_metric_to_m(_decimal(elev.group(1)), elev.group(2), infer_small_as_m=False)
        # Explicit mm/cm is converted; unit-less elevation is preserved as drawing/project elevation.
        if not -10000 <= elevation_m <= 10000:
            elevation_m=None

    return ParsedTextFacts(
        raw_text=raw,
        diameter_mm=diameter_mm,
        diameter_source=diameter_source,
        material=_detect_material(plain),
        systems=_detect_systems(raw),
        height_m=height_m,
        elevation_m=elevation_m,
        vertical_directive=_vertical_directive(plain),
    )


def _entity_geometry(entity: CadEntity):
    if isinstance(entity, CadLine):
        return LineString([(entity.start.x,entity.start.y),(entity.end.x,entity.end.y)])
    if isinstance(entity, CadPolyline):
        return LineString([(p.x,p.y) for p in entity.points])
    if isinstance(entity, CadInsert):
        return Point(entity.position.x,entity.position.y)
    return None


class TextEvidenceIndex:
    """Spatially associate meaningful CAD text with nearby MEP geometry.

    Text remains evidence, not ground truth. The index only exposes parsed facts and the
    nearest relevant snippets; callers decide whether those facts are strong enough to
    create or merely review a BIM element.
    """

    def __init__(self, document: CadDocument, *, radius_m: float=.60):
        self.document=document
        self.radius_m=max(float(radius_m),0.01)
        self._texts=[]
        self._facts=[]
        self._points=[]
        for entity in document.entities:
            if not isinstance(entity,CadText):
                continue
            facts=parse_text_facts(entity.text)
            if not facts.has_semantic_fact:
                continue
            self._texts.append(entity)
            self._facts.append(facts)
            self._points.append(Point(entity.position.x,entity.position.y))
        self._tree=STRtree(self._points) if self._points else None

    @property
    def semantic_text_count(self)->int:
        return len(self._texts)

    def for_entity(self, entity: CadEntity) -> AssociatedTextEvidence:
        geom=_entity_geometry(entity)
        if geom is None or self._tree is None:
            return AssociatedTextEvidence()
        indices=self._tree.query(geom.buffer(self.radius_m))
        ranked=[]
        for raw_index in indices:
            idx=int(raw_index)
            distance=float(geom.distance(self._points[idx]))
            if distance <= self.radius_m + 1e-9:
                ranked.append((distance,self._texts[idx],self._facts[idx]))
        ranked.sort(key=lambda item:(item[0],item[1].id))
        if not ranked:
            return AssociatedTextEvidence()

        diameter=None;diameter_source=None;material=None;height=None;elevation=None;vertical=None
        vertical_anchor=None
        systems=[];chosen=[]
        for distance,text,facts in ranked:
            used=False
            if diameter is None and facts.diameter_mm is not None:
                diameter=facts.diameter_mm;diameter_source=facts.diameter_source;used=True
            if material is None and facts.material is not None:
                material=facts.material;used=True
            for system in facts.systems:
                if system not in systems:
                    systems.append(system);used=True
            if height is None and facts.height_m is not None:
                height=facts.height_m;used=True
            if elevation is None and facts.elevation_m is not None:
                elevation=facts.elevation_m;used=True
            if vertical is None and facts.vertical_directive is not None:
                vertical=facts.vertical_directive;vertical_anchor=(text.position.x,text.position.y);used=True
            if used:
                chosen.append((distance,text,facts))
            if diameter is not None and material is not None and height is not None and elevation is not None and vertical is not None:
                break
        if not chosen:
            return AssociatedTextEvidence()
        # Keep each text once in distance order; raw evidence is intentionally bounded.
        text_ids=tuple(item[1].id for item in chosen[:5])
        raw=' | '.join(item[1].text for item in chosen[:5])
        return AssociatedTextEvidence(
            diameter_mm=diameter,
            diameter_source=diameter_source,
            material=material,
            systems=tuple(systems),
            height_m=height,
            elevation_m=elevation,
            vertical_directive=vertical,
            raw_text=raw or None,
            text_ids=text_ids,
            nearest_distance_m=chosen[0][0],
            anchor_x=(vertical_anchor[0] if vertical_anchor is not None else chosen[0][1].position.x),
            anchor_y=(vertical_anchor[1] if vertical_anchor is not None else chosen[0][1].position.y),
        )
